const input = $input.first().json;
if (!input || !input.config || !input.batch || !input.pair) {
  throw new Error('Expected config, batch and pair objects from the batch controller.');
}
const config = input.config;
const batch = input.batch;
const pair = input.pair;
if (!/^https:\/\/[^/]+\.supabase\.co$/i.test(config.supabase_url || '')) {
  throw new Error('Set a valid Supabase project URL in the batch controller.');
}
const permittedModels = new Set(['gpt-5.4-mini', 'gpt-5.4-nano']);
for (const field of ['question_model', 'page_map_model', 'mark_scheme_model', 'metadata_model', 'repair_model']) {
  if (!permittedModels.has(config[field])) {
    throw new Error('Unsupported guarded model in config.' + field + ': ' + config[field]);
  }
}
const reservations = config.stage_reservations_usd || {};
for (const [stage, amount] of Object.entries(reservations)) {
  if (!(Number(amount) > 0) || Number(amount) > 0.25) {
    throw new Error('Each stage reservation must be greater than $0 and no more than $0.25: ' + stage);
  }
}
if (!batch.id || !batch.batch_key) throw new Error('The Supabase batch row is missing.');
if (!Array.isArray(pair.documents) || pair.documents.length !== 2) {
  throw new Error('Each paper pair must contain exactly a question paper and mark scheme.');
}
const types = new Set(pair.documents.map((document) => document.document_type));
if (!types.has('question_paper') || !types.has('mark_scheme')) {
  throw new Error('The pair must contain one question paper and one mark scheme.');
}
for (const document of pair.documents) {
  if (!/^https:\/\//i.test(document.source_url || '')) {
    throw new Error('Every document needs an HTTPS source URL.');
  }
}
const paperType = String(pair.paper_variant || '').charAt(0);
// Expected paper totals are a property of the syllabus, not a universal
// constant -- 9709 splits Papers 1/3 (75 marks) from Papers 4-6 (50 marks),
// while IGCSE 0606's two papers are BOTH 80 marks. Keying explicitly on
// syllabus_code and throwing on anything unrecognised means a future third
// syllabus cannot silently inherit the wrong numbers from whichever branch
// happens to run first -- it has to be added here on purpose.
let expectedTotalMarks;
if (pair.syllabus_code === '9709') {
  expectedTotalMarks = ['1', '3'].includes(paperType) ? 75 : 50;
} else if (pair.syllabus_code === '0606') {
  if (!['1', '2'].includes(paperType)) {
    throw new Error('Unrecognized 0606 paper variant: ' + pair.paper_variant);
  }
  expectedTotalMarks = 80;
} else {
  throw new Error('No expected-marks rule is defined for syllabus_code ' + pair.syllabus_code + '.');
}
const sourceKey = [
  pair.qualification,
  pair.syllabus_code,
  pair.year,
  pair.exam_session,
  pair.paper_variant,
].join(':');
const idempotencyKey = ['budget-v2.1', batch.batch_key, sourceKey].join(':');
return [{
  json: {
    config,
    batch,
    pair,
    batch_position: input.batch_position,
    batch_size: input.batch_size,
    source_key: sourceKey,
    idempotency_key: idempotencyKey,
    expected_total_marks: expectedTotalMarks,
  },
}];

const response = $input.first().json;
const rows = Array.isArray(response) ? response : (response?.id ? [response] : []);
const state = $('Validate Paper Input').first().json;
if (!rows.length) return [{ json: { ...state, skip_existing: false } }];
const run = rows[0];
const finishedStatuses = [
  'awaiting_review',
  'approved',
  'published',
  'search_pending',
  'complete',
];
if (finishedStatuses.includes(run.status)) {
  return [{
    json: {
      ...state,
      skip_existing: true,
      existing_run: run,
    },
  }];
}
if (run.status === 'processing') {
  throw new Error(
    'This paper already has a processing run. Inspect ingestion run ' + run.id +
    ' before retrying to avoid duplicate API work.'
  );
}
return [{ json: { ...state, skip_existing: false, retry_run: run } }];

const state = $input.first().json;
return [{
  json: {
    success: true,
    skipped_existing: true,
    message: 'This paper was already staged or published, so no OCR or OpenAI call was made.',
    ingestion_run_id: state.existing_run.id,
    paper_id: state.existing_run.paper_id,
    batch_id: state.batch.id,
    batch_position: state.batch_position,
    batch_size: state.batch_size,
    config: state.config,
    actual_cost_usd: 0,
    ready_for_approval: state.existing_run.validation_report?.passed === true,
  },
}];

const state = $input.first().json;
return [{
  json: {
    ...state,
    paper_row: {
      qualification: state.pair.qualification,
      syllabus_code: state.pair.syllabus_code,
      subject: state.pair.subject,
      year: state.pair.year,
      exam_session: state.pair.exam_session,
      paper_variant: state.pair.paper_variant,
      status: 'staging',
    },
  },
}];

const response = $input.first().json;
const paper = Array.isArray(response) ? response[0] : response;
const state = $('Prepare Paper Upsert').first().json;
if (!paper?.id) throw new Error('Supabase did not return the paper row.');
return [{
  json: {
    ...state,
    paper_id: paper.id,
    run_body: {
      paper_id: paper.id,
      idempotency_key: state.idempotency_key,
      mode: 'production',
      status: 'processing',
      review_status: 'pending',
      source_key: state.source_key,
      ocr_model: state.config.ocr_model,
      extraction_model: state.config.question_model,
      verifier_model: null,
      attempt_count: Number(state.retry_run?.attempt_count || 0) + 1,
      source_summary: {
        batch_id: state.batch.id,
        batch_key: state.batch.batch_key,
        batch_position: state.batch_position,
        documents: state.pair.documents,
      },
      extraction_summary: {},
      verifier_report: {},
      validation_report: {},
      started_at: new Date().toISOString(),
      finished_at: null,
    },
  },
}];

const response = $input.first().json;
const run = Array.isArray(response) ? response[0] : response;
const state = $('Prepare Ingestion Run').first().json;
if (!run?.id) throw new Error('Supabase did not return the ingestion run.');
return state.pair.documents.map((document, index) => ({
  json: {
    config: state.config,
    batch: state.batch,
    pair: state.pair,
    batch_position: state.batch_position,
    batch_size: state.batch_size,
    paper_id: state.paper_id,
    ingestion_run_id: run.id,
    source_key: state.source_key,
    idempotency_key: state.idempotency_key,
    expected_total_marks: state.expected_total_marks,
    document,
    mistral_request: {
      model: state.config.ocr_model,
      document: {
        type: 'document_url',
        document_url: document.source_url,
      },
      bbox_annotation_format: {
        type: 'json_schema',
        json_schema: {
          name: 'shamo_instructional_asset',
          strict: true,
          schema: {"type":"object","properties":{"asset_type":{"type":"string","enum":["graph","geometry_diagram","mechanics_diagram","table","number_line","coordinate_grid","decorative_or_irrelevant","other_instructional"]},"description":{"type":"string"},"required_to_solve":{"type":"boolean"},"likely_question_number":{"anyOf":[{"type":"integer"},{"type":"null"}]},"part_path":{"type":"array","maxItems":4,"items":{"type":"string"}},"mathematical_details":{"type":"object","properties":{"visible_labels":{"type":"array","items":{"type":"string"}},"equations":{"type":"array","items":{"type":"string"}},"coordinates":{"type":"array","items":{"type":"string"}},"measurements":{"type":"array","items":{"type":"string"}},"relationships":{"type":"array","items":{"type":"string"}}},"required":["visible_labels","equations","coordinates","measurements","relationships"],"additionalProperties":false}},"required":["asset_type","description","required_to_solve","likely_question_number","part_path","mathematical_details"],"additionalProperties":false},
        },
      },
      include_image_base64: true,
      confidence_scores_granularity: 'page',
    },
  },
  pairedItem: { item: index },
}));

const responses = $input.all();
const sources = $('Expand Paper Documents').all();
if (responses.length !== 2 || sources.length !== 2) {
  throw new Error('OCR must return exactly two document responses.');
}
return responses.map((item, index) => {
  const source = sources[index].json;
  const ocr = item.json;
  if (!Array.isArray(ocr.pages) || !ocr.pages.length) {
    throw new Error('Mistral OCR returned no pages for ' + source.document.document_type + '.');
  }
  return {
    json: {
      ...source,
      ocr_model_returned: ocr.model || source.config.ocr_model,
      ocr_usage: ocr.usage_info || {},
      pages: ocr.pages,
    },
  };
});

const documents = $input.all().map((item) => item.json);
if (documents.length !== 2) throw new Error('Expected exactly two OCR documents.');
const first = documents[0];
const pageRows = [];
const compactDocuments = [];
for (const document of documents) {
  const compactPages = [];
  for (const page of document.pages) {
    const pageNumber = Number(page.index) + 1;
    pageRows.push({
      ingestion_run_id: document.ingestion_run_id,
      document_type: document.document.document_type,
      page_number: pageNumber,
      raw_markdown: page.markdown || '',
      ocr_confidence: page.confidence ?? page.confidence_score ?? null,
    });
    compactPages.push({
      page_number: pageNumber,
      markdown: page.markdown || '',
      images: (page.images || []).map((image, imageIndex) => ({
        source_image_index: imageIndex,
        id: image.id || null,
        top_left_x: image.top_left_x ?? null,
        top_left_y: image.top_left_y ?? null,
        bottom_right_x: image.bottom_right_x ?? null,
        bottom_right_y: image.bottom_right_y ?? null,
        image_annotation: image.image_annotation || null,
      })),
    });
  }
  compactDocuments.push({
    document_type: document.document.document_type,
    source_url: document.document.source_url,
    page_count: document.pages.length,
    ocr_model: document.ocr_model_returned,
    pages: compactPages,
  });
}
return [{
  json: {
    config: first.config,
    batch: first.batch,
    pair: first.pair,
    batch_position: first.batch_position,
    batch_size: first.batch_size,
    paper_id: first.paper_id,
    ingestion_run_id: first.ingestion_run_id,
    source_key: first.source_key,
    idempotency_key: first.idempotency_key,
    expected_total_marks: first.expected_total_marks,
    ocr_documents: documents,
    compact_documents: compactDocuments,
    known_documents: compactDocuments.map((document) => ({
      document_type: document.document_type,
      source_url: document.source_url,
      source_url_hash: null,
      page_count: document.page_count,
      ocr_model: document.ocr_model,
    })),
    ocr_page_rows: pageRows,
  },
}];

const state = $('Build OCR State').first().json;
const openaiIdempotencyKey = state.idempotency_key + ':question_paper_extraction';
return [{
  json: {
    ...state,
    openai_idempotency_key: openaiIdempotencyKey,
    reserve_body: {
      requested_batch_id: state.batch.id,
      requested_ingestion_run_id: state.ingestion_run_id,
      requested_idempotency_key: openaiIdempotencyKey,
      requested_provider: 'openai',
      requested_model: state.config.question_model,
      requested_operation: 'question_paper_extraction',
      requested_reserved_usd: state.config.stage_reservations_usd.question_paper,
    },
  },
}];

const reservationResponse = $input.first().json;
const reservation = Array.isArray(reservationResponse) ? reservationResponse[0] : reservationResponse;
const state = $('Prepare Question Paper Reservation').first().json;
if (!reservation?.cost_event_id) throw new Error('Question-paper budget reservation was not returned.');
const questionPaper = state.compact_documents.find((document) => document.document_type === 'question_paper');
if (!questionPaper) throw new Error('Question-paper OCR document is missing.');
const prompt = [
  'Extract only the question paper from this official Cambridge Mathematics paper.',
  'The paper identity is supplied in the request. Its expected total is ' + state.expected_total_marks + ' marks.',
  'Use the PDF as the visual source of truth and OCR JSON as a page-indexed aid.',
  'Return every main question in numerical order and make question totals add exactly to the expected paper total.',
  'Transcribe every mathematical sign, exponent, radical, limit, coordinate and inequality exactly.',
  'A main question number is an integer. Never put labels such as (a) in question_number.',
  'Create a part only when a label such as (a), (b), (i) or (ii) is visibly printed.',
  'For nested parts use paths such as ["a","i"]. Never include the main question number in label_path.',
  'For an unparted question use parts=[] and put the complete question in stem_markdown.',
  'Do not duplicate an instruction between stem_markdown and a part prompt.',
  'When a parent part has child parts, keep its shared prompt but set its marks to null unless a separate mark value is visibly printed for the parent.',
  'Use 1-based PDF page numbers. Ignore answer lines, barcodes, footers and margin instructions.',
  'Include only diagrams, graphs and tables needed to understand or solve a question.',
  'Every asset must match an OCR image using its exact page number and zero-based source_image_index.',
  'Do not extract mark-scheme content or topic metadata in this call.',
].join('\n');
return [{
  json: {
    ...state,
    cost_event_id: reservation.cost_event_id,
    question_paper_request: {
      model: state.config.question_model,
      reasoning: { effort: 'medium' },
      store: false,
      max_output_tokens: 22000,
      input: [
        { role: 'system', content: prompt },
        {
          role: 'user',
          content: [
            {
              type: 'input_text',
              text: JSON.stringify({
                paper: {
                  qualification: state.pair.qualification,
                  syllabus_code: state.pair.syllabus_code,
                  subject: state.pair.subject,
                  year: state.pair.year,
                  exam_session: state.pair.exam_session,
                  paper_variant: state.pair.paper_variant,
                  expected_total_marks: state.expected_total_marks,
                },
                question_paper_ocr: questionPaper,
              }),
            },
            ...(state.config.attach_source_pdf === false
              ? []
              : [{ type: 'input_file', file_url: questionPaper.source_url }]),
          ],
        },
      ],
      text: {
        format: {
          type: 'json_schema',
          name: 'shamo_v2_question_paper',
          strict: true,
          schema: {"type":"object","properties":{"questions":{"type":"array","minItems":1,"items":{"type":"object","properties":{"question_number":{"type":"integer","minimum":1},"stem_markdown":{"type":"string"},"total_marks":{"type":"integer","minimum":0},"source_page_numbers":{"type":"array","minItems":1,"items":{"type":"integer","minimum":1}},"parts":{"type":"array","items":{"type":"object","properties":{"label_path":{"type":"array","minItems":1,"maxItems":4,"items":{"type":"string","pattern":"^[A-Za-z0-9]+$"}},"prompt_markdown":{"type":"string"},"marks":{"anyOf":[{"type":"integer"},{"type":"null"}]},"source_page_numbers":{"type":"array","minItems":1,"items":{"type":"integer","minimum":1}},"sort_order":{"type":"integer","minimum":0}},"required":["label_path","prompt_markdown","marks","source_page_numbers","sort_order"],"additionalProperties":false}},"assets":{"type":"array","items":{"type":"object","properties":{"part_path":{"type":"array","maxItems":4,"items":{"type":"string","pattern":"^[A-Za-z0-9]+$"}},"document_type":{"type":"string","enum":["question_paper","mark_scheme"]},"source_page_number":{"type":"integer","minimum":1},"source_image_index":{"type":"integer","minimum":0},"asset_type":{"type":"string","enum":["graph","geometry_diagram","mechanics_diagram","table","number_line","coordinate_grid","other_instructional"]},"bounding_box":{"anyOf":[{"type":"object","properties":{"top_left_x":{"type":"number"},"top_left_y":{"type":"number"},"bottom_right_x":{"type":"number"},"bottom_right_y":{"type":"number"}},"required":["top_left_x","top_left_y","bottom_right_x","bottom_right_y"],"additionalProperties":false},{"type":"null"}]},"description":{"type":"string"},"mathematical_details":{"type":"object","properties":{"visible_labels":{"type":"array","items":{"type":"string"}},"equations":{"type":"array","items":{"type":"string"}},"coordinates":{"type":"array","items":{"type":"string"}},"measurements":{"type":"array","items":{"type":"string"}},"relationships":{"type":"array","items":{"type":"string"}}},"required":["visible_labels","equations","coordinates","measurements","relationships"],"additionalProperties":false},"required_to_solve":{"type":"boolean"}},"required":["part_path","document_type","source_page_number","source_image_index","asset_type","bounding_box","description","mathematical_details","required_to_solve"],"additionalProperties":false}}},"required":["question_number","stem_markdown","total_marks","source_page_numbers","parts","assets"],"additionalProperties":false}}},"required":["questions"],"additionalProperties":false},
        },
      },
    },
  },
}];

const response = $input.first().json;
const state = $('Build Question Paper Request').first().json;
if (response.status === 'incomplete') {
  throw new Error('Question-paper extraction was incomplete: ' + JSON.stringify(response.incomplete_details || {}));
}
const message = (response.output || []).find((entry) => entry.type === 'message');
if (!message) throw new Error('Question-paper extraction returned no message output.');
const refusal = (message.content || []).find((entry) => entry.type === 'refusal');
if (refusal) throw new Error('Question-paper extraction refused: ' + (refusal.refusal || 'unknown refusal'));
const outputText = (message.content || []).find((entry) => entry.type === 'output_text');
if (!outputText?.text) throw new Error('Question-paper extraction returned no structured text.');
const extracted = JSON.parse(outputText.text);
if (!Array.isArray(extracted.questions) || !extracted.questions.length) {
  throw new Error('Question-paper extraction has no questions.');
}
const model = state.config.question_model;

const usage = response.usage || {};
const inputTokens = Number(usage.input_tokens || 0);
const cachedInputTokens = Number(usage.input_tokens_details?.cached_tokens || 0);
const outputTokens = Number(usage.output_tokens || 0);
const reportedTotalTokens = Number(usage.total_tokens || 0);
// Any token the provider counts but we do not price is unbilled in our ledger.
const unaccountedTokens = reportedTotalTokens > 0
  ? Math.max(0, reportedTotalTokens - inputTokens - outputTokens)
  : 0;
const prices = state.config.openai_prices_per_million[model];
if (!prices) throw new Error('No price configuration exists for ' + model + '.');
const actualCostUsd =
  Math.max(0, inputTokens - cachedInputTokens) * Number(prices.input) / 1000000 +
  cachedInputTokens * Number(prices.cached_input) / 1000000 +
  outputTokens * Number(prices.output) / 1000000;
const usageAudit = {
  usage_raw: usage,
  reported_total_tokens: reportedTotalTokens,
  unaccounted_tokens: unaccountedTokens,
  priced_input_tokens: inputTokens,
  priced_output_tokens: outputTokens,
  response_id: response.id || null,
  model_reported: response.model || null,
};
return [{
  json: {
    ...state,
    question_paper_questions: extracted.questions,
    extraction_response_ids: [response.id || null],
    api_events: [{
      operation: 'question_paper_extraction',
      model,
      input_tokens: inputTokens,
      cached_input_tokens: cachedInputTokens,
      output_tokens: outputTokens,
      actual_cost_usd: Number(actualCostUsd.toFixed(8)),
      usage_audit: usageAudit,
    }],
    finalize_cost_body: {
      requested_cost_event_id: state.cost_event_id,
      requested_input_tokens: inputTokens,
      requested_cached_input_tokens: cachedInputTokens,
      requested_output_tokens: outputTokens,
      requested_actual_usd: Number(actualCostUsd.toFixed(8)),
      requested_provider_request_id: response.id || null,
    },
  },
}];

const state = $('Restore Question Paper State').first().json;
const openaiIdempotencyKey = state.idempotency_key + ':mark_scheme_page_map';
return [{
  json: {
    ...state,
    openai_idempotency_key: openaiIdempotencyKey,
    reserve_body: {
      requested_batch_id: state.batch.id,
      requested_ingestion_run_id: state.ingestion_run_id,
      requested_idempotency_key: openaiIdempotencyKey,
      requested_provider: 'openai',
      requested_model: state.config.page_map_model,
      requested_operation: 'mark_scheme_page_map',
      requested_reserved_usd: state.config.stage_reservations_usd.page_map,
    },
  },
}];

const reservationResponse = $input.first().json;
const reservation = Array.isArray(reservationResponse) ? reservationResponse[0] : reservationResponse;
const state = $('Prepare Page Map Reservation').first().json;
if (!reservation?.cost_event_id) throw new Error('Page-map budget reservation was not returned.');
const markScheme = state.compact_documents.find((document) => document.document_type === 'mark_scheme');
if (!markScheme) throw new Error('Mark-scheme OCR document is missing.');
const prompt = [
  'Map the official Cambridge mark scheme by main question number.',
  'This is routing only: do not transcribe answers and do not solve anything.',
  'For every visible main question, return every 1-based PDF page on which its mark-scheme table continues.',
  'A page can belong to two questions when one ends and the next begins on that page.',
  'Do not confuse part labels, mark values, page numbers or totals with main question numbers.',
  'Use the printed paper total when visible. Otherwise return source_total_marks=null.',
].join('\n');
return [{
  json: {
    ...state,
    cost_event_id: reservation.cost_event_id,
    page_map_request: {
      model: state.config.page_map_model,
      reasoning: { effort: 'low' },
      store: false,
      max_output_tokens: 3000,
      input: [
        { role: 'system', content: prompt },
        {
          role: 'user',
          content: [{
            type: 'input_text',
            text: JSON.stringify({
              paper_variant: state.pair.paper_variant,
              expected_question_numbers: state.question_paper_questions.map((question) => question.question_number),
              mark_scheme_ocr: markScheme,
            }),
          }],
        },
      ],
      text: {
        format: {
          type: 'json_schema',
          name: 'shamo_v2_mark_scheme_page_map',
          strict: true,
          schema: {"type":"object","properties":{"source_question_count":{"anyOf":[{"type":"integer"},{"type":"null"}]},"source_total_marks":{"anyOf":[{"type":"integer"},{"type":"null"}]},"question_pages":{"type":"array","minItems":1,"items":{"type":"object","properties":{"question_number":{"type":"integer","minimum":1},"page_numbers":{"type":"array","minItems":1,"items":{"type":"integer","minimum":1}}},"required":["question_number","page_numbers"],"additionalProperties":false}}},"required":["source_question_count","source_total_marks","question_pages"],"additionalProperties":false},
        },
      },
    },
  },
}];

const response = $input.first().json;
const state = $('Build Page Map Request').first().json;
if (response.status === 'incomplete') throw new Error('Page-map extraction was incomplete.');
const message = (response.output || []).find((entry) => entry.type === 'message');
const outputText = (message?.content || []).find((entry) => entry.type === 'output_text');
if (!outputText?.text) throw new Error('Page-map extraction returned no structured text.');
const extracted = JSON.parse(outputText.text);
const pageMap = {};
for (const entry of extracted.question_pages || []) {
  const number = Number(entry.question_number);
  const pages = [...new Set((entry.page_numbers || []).map(Number))].sort((a, b) => a - b);
  if (pageMap[number]) throw new Error('Page map contains duplicate question ' + number + '.');
  pageMap[number] = pages;
}
const model = state.config.page_map_model;

const usage = response.usage || {};
const inputTokens = Number(usage.input_tokens || 0);
const cachedInputTokens = Number(usage.input_tokens_details?.cached_tokens || 0);
const outputTokens = Number(usage.output_tokens || 0);
const reportedTotalTokens = Number(usage.total_tokens || 0);
// Any token the provider counts but we do not price is unbilled in our ledger.
const unaccountedTokens = reportedTotalTokens > 0
  ? Math.max(0, reportedTotalTokens - inputTokens - outputTokens)
  : 0;
const prices = state.config.openai_prices_per_million[model];
if (!prices) throw new Error('No price configuration exists for ' + model + '.');
const actualCostUsd =
  Math.max(0, inputTokens - cachedInputTokens) * Number(prices.input) / 1000000 +
  cachedInputTokens * Number(prices.cached_input) / 1000000 +
  outputTokens * Number(prices.output) / 1000000;
const usageAudit = {
  usage_raw: usage,
  reported_total_tokens: reportedTotalTokens,
  unaccounted_tokens: unaccountedTokens,
  priced_input_tokens: inputTokens,
  priced_output_tokens: outputTokens,
  response_id: response.id || null,
  model_reported: response.model || null,
};
return [{
  json: {
    ...state,
    mark_scheme_page_map: pageMap,
    paper_summary: {
      question_count_from_source: Number.isInteger(extracted.source_question_count)
        ? extracted.source_question_count
        : null,
      total_marks_from_source: state.expected_total_marks,
      mark_scheme_total_marks_reported: Number.isInteger(extracted.source_total_marks)
        ? extracted.source_total_marks
        : null,
    },
    extraction_response_ids: [...(state.extraction_response_ids || []), response.id || null],
    api_events: [...(state.api_events || []), {
      operation: 'mark_scheme_page_map',
      model,
      input_tokens: inputTokens,
      cached_input_tokens: cachedInputTokens,
      output_tokens: outputTokens,
      actual_cost_usd: Number(actualCostUsd.toFixed(8)),
      usage_audit: usageAudit,
    }],
    finalize_cost_body: {
      requested_cost_event_id: state.cost_event_id,
      requested_input_tokens: inputTokens,
      requested_cached_input_tokens: cachedInputTokens,
      requested_output_tokens: outputTokens,
      requested_actual_usd: Number(actualCostUsd.toFixed(8)),
      requested_provider_request_id: response.id || null,
    },
  },
}];

// Deterministic parser for Cambridge mark-scheme tables.
//
// WHY THIS REPLACES A MODEL CALL
// ------------------------------
// Mistral OCR already emits mark schemes as markdown tables with the printed
// Question / Answer / Marks / Guidance columns intact. The pipeline used to
// discard that structure and pay gpt-5.4-nano to reconstruct it from raw text,
// one call per question. Every mark-row defect class observed in batches 1 and
// 2 came from that: answer/marks bleeding into guidance, table body rows
// counted as mark rows, fabricated mark codes, wrong part paths, and mishandled
// blank Marks cells.
//
// A parser cannot hallucinate a mark code. That is the whole argument.
//
// This module is authored as a real ES module so it can be unit-tested in
// milliseconds, and is inlined into the n8n Code node `Parse Mark Scheme
// Tables` by build_budget_v2_workflows.mjs via lib/inline_module.mjs. The
// static validator asserts the inlined text matches this file byte for byte,
// so the two can never drift.
//
// Verified against real OCR from all six staged batch-2 papers. The five
// structures below are not hypothetical -- each one appears in the corpus and
// each one caused a real defect.

// ---------------------------------------------------------------------------
// Tokens
// ---------------------------------------------------------------------------

// One printed Cambridge mark code.
//
// Deliberately permissive in three places, each learned from real OCR:
//   - `B2,1,0` (award 2, 1 or 0) is real; the old regex rejected it and the
//     model silently rewrote it to `B2`.
//   - The dependency asterisk appears on BOTH sides. `*M1` is the common form,
//     but 9709/62 page 11 prints `M1*`. Rejecting the trailing form dropped a
//     whole mark row and made 7(c) reconcile at 3 against a printed 4.
//   - `FT` may be attached (`A1FT`) or spaced (`A1 FT`).
// DA is as real as DM and DB. Cambridge's own generic marking principles define
// "DM or DA" as a method or accuracy mark dependent on a previous mark, and
// 9709/63 M/J 2024 Q6(b) prints a bare DA1. Its absence here blocked that whole
// paper on INVALID_MARK_CODE against a correctly-read printed code, and targeted
// repair could not clear it because there was nothing wrong with the extraction.
//
// Longer alternatives must precede shorter ones, so DM/DB/DA are tried before
// the single letters and DA1 stays one code rather than parsing as D + A1.
const ONE_CODE = String.raw`\*?(?:DM|DB|DA|M|A|B)\d+\*?(?:\s*FT)?(?:\s*,\s*\d+)*`;

// A whole Marks cell: one or more codes, e.g. `M1`, `*M1`, `A1 FT`, `B1 B1`.
//
// The separator is `\s*`, not `\s+`, because Cambridge also prints them run
// together. 9709/61 O/N 2025 Q6(a) awards two marks in one cell as `B1B1`, and
// requiring a space meant the cell was not recognised as a Marks cell at all --
// so the codes were appended to the answer text and TWO MARKS WERE LOST, with
// the part reconciling at 3 against a printed 5.
//
// Safe because the pattern is anchored to a whole cell. `M1A1B1` appearing in
// the middle of a Special Case sentence is not a whole cell and still cannot
// match. `DB1` stays one code, since the alternation tries `DM` and `DB` before
// the single letters.
const CODE_BODY = new RegExp(`^${ONE_CODE}(?:\\s*${ONE_CODE})*$`, "i");

// A printed per-part subtotal: a bare integer alone in the Marks column.
const SUBTOTAL = /^\d{1,2}$/;

// A Question cell: `7`, `7(b)`, `9(a)(ii)`. The main number is an integer and
// never enters part_path.
const QUESTION_CELL = /^(\d{1,2})((?:\s*\([A-Za-z0-9]{1,3}\))*)$/;

// Opens an alternative block. `Method 1` explicitly CLOSES one -- it marks the
// primary method, not an alternative.
const ALT_HEADER = /^(?:alternative\s+(?:method|solution)|method\s*(\d+))\b/i;

// A bare alternative header, with no "Method"/"Solution" qualifier: `Alternative`,
// `Alternative 1`, `Alternative 2`, `Alternative version`. Confirmed printed
// verbatim across several IGCSE 0606 2024-2025 mark schemes (source review,
// 20 August 2026) -- ALT_HEADER above requires "method" or "solution" right
// after the word, so this shorter form fell through to ordinary content and
// got appended onto the PRECEDING row's `content_markdown` by the multi-line
// continuation step, corrupting it (e.g. a correct final answer ending in the
// literal text "\nAlternative"). Anchored to the WHOLE cell (not just a
// prefix) so genuine prose that happens to start with the word "alternative"
// is never mistaken for a header.
const BARE_ALT_HEADER = /^alternative(?:\s+version)?\s*\d{0,2}\s*:?$/i;

// A qualifier limiting how far the alternative block reaches:
//
//   Alternative Method 2 for first 4 marks of Question 6(b)
//   Alternative Method 1 for first two marks of Question 8(b)
//
// This is load-bearing, not decoration. Rows beyond the Nth are SHARED by every
// method -- typically the final answer -- so absorbing them into the alternative
// block removes them from the primary sum and silently loses a mark. That is
// exactly what happened to 9709/12 M/J 2024 Q6(b): 4 primary marks staged
// against a printed 5, because the closing `32/3` answer row was swallowed.
//
// Cambridge writes the count as a digit or a word, so both are accepted.
const ALT_MARK_CAP = /\bfor\s+(?:the\s+)?first\s+(\d{1,2}|one|two|three|four|five|six|seven|eight|nine|ten)\s+marks?\b/i;
const WORD_NUMBERS = {
  one: 1, two: 2, three: 3, four: 4, five: 5,
  six: 6, seven: 7, eight: 8, nine: 9, ten: 10,
};

/** Read the "for first N marks" cap from a block header, or null if absent. */
function alternativeMarkCap(header) {
  const match = String(header ?? "").match(ALT_MARK_CAP);
  if (!match) return null;
  const token = match[1].toLowerCase();
  return WORD_NUMBERS[token] ?? Number(token);
}

// Opens a Special Case block: `Special Case if no integration seen. Maximum
// M1A1B1 for 3 marks`. Structurally identical to an alternative header -- empty
// Marks cell, announcement in the Answer column, awards on the rows beneath.
//
// Semantically it is NOT an alternative method. An SC is a capped consolation
// award for a wrong approach, and the repository convention is explicit that
// special-case marks must not inflate primary mark coverage. Both kinds are
// therefore excluded from the primary sum, but they are tracked separately in
// `special_case_groups` so the validator can tell them apart and so the
// distinction survives if an is_special_case column is added later.
const SC_HEADER = /^special\s+case\b/i;

// A Marks code that OCR pushed to the front of the Guidance cell, because the
// printed table had more columns than Mistral emitted. Anchored, so a code
// mentioned mid-sentence ("If 0 scored, SC: ... B1") never matches.
const LIFT = new RegExp(`^\\*\\*\\s*(${ONE_CODE}(?:\\s+${ONE_CODE})*)\\s*\\*\\*\\s*`, "i");

// Page furniture that is never table content.
const PAGE_NOISE = [
  /^\d{4}\/\d{2}$/,
  /^Cambridge International/i,
  /^©/,
  /^Page \d+ of \d+$/i,
  /^#+\s*PUBLISHED\s*$/i,
  /^PUBLISHED$/i,
  /^#/,
];

/**
 * Strip markdown bold from a whole table cell.
 *
 * Cell-bounded stripping is what makes the dependency asterisk unambiguous.
 * `***M1**` inside a pipe-delimited cell can only be `**` + `*M1` + `**`, so it
 * resolves to `*M1` with the dependency marker intact. The old code sliced
 * prefixes and suffixes off model output, after the cell boundary was already
 * gone, and lost the asterisk.
 *
 * The `inner.includes("**")` guard is load-bearing: without it a guidance cell
 * like `**M1** ... scores **B1**` strips to `M1** ... scores **B1` and corrupts
 * the text.
 */
function stripBold(raw) {
  let text = String(raw ?? "").trim();
  for (;;) {
    if (text.length > 4 && text.startsWith("**") && text.endsWith("**")) {
      const inner = text.slice(2, -2);
      if (inner.includes("**")) break;
      text = inner.trim();
      continue;
    }
    if (text.length > 4 && text.startsWith("__") && text.endsWith("__")) {
      text = text.slice(2, -2).trim();
      continue;
    }
    break;
  }
  // Unclosed bold. Mistral sometimes drops the closing `**`, e.g. paper 22
  // page 8 emits `**M1FT` where the paper prints `M1FT`. Only safe when there
  // is no later `**` in the cell -- otherwise this is a Guidance cell whose
  // leading code belongs to the LIFT path, and eating the marker here would
  // destroy the signal that the Marks column was merged in.
  if (text.startsWith("**") && !text.slice(2).includes("**")) {
    text = text.slice(2).trim();
  }
  return text;
}

// Mistral OCR occasionally spells the LaTeX escape character out as the
// English word "backslash" instead of emitting `\`, and separately escapes
// grouping braces that should be plain: `\backslash frac\{1\}\{2\}` for a
// printed `\frac{1}{2}`. Confirmed present in the raw OCR record itself, not
// introduced downstream -- verbatim on 9709/31 M/J 2024 mark scheme page 7
// and 9709/12 O/N 2024 page 21 -- and measured at 79 affected rows across 18
// already-published papers before backfill. Repaired here so a future batch
// cannot carry it into the database again.
//
// Two passes:
//   1. `\backslash <command>` collapses to `\<command>` when the following
//      word is a real LaTeX command that needs the backslash (frac, sqrt,
//      theta, text, left, ...). The word "backslash" and its one trailing
//      space are simply deleted; the real backslash already present in the
//      source survives and now sits directly before the command name.
//   2. Anything else -- `\backslash i` (the imaginary unit), `\backslash c`
//      (a bare variable), `\backslash their` (the follow-through word),
//      `\backslash θ` (a literal Greek letter) -- has no command to keep, so
//      the whole `\backslash ` span is deleted outright, leaving the
//      following character as plain text. Confirmed against uncorrupted
//      sibling rows in the same corpus that write these bare, e.g. published
//      guidance elsewhere reads plain "...+ i" with no backslash at all.
//
// A trailing pass then unescapes any remaining `\{` / `\}` back to plain
// grouping braces -- except immediately after `\left` / `\right`, where an
// escaped brace is correct LaTeX for a literal brace DELIMITER and must be
// left alone. `\left\{ ... \right\}` appears throughout this same corpus as
// legitimate, uncorrupted notation, so unescaping it unconditionally would
// trade one corruption for another.
const BACKSLASH_WORD_COMMANDS = new Set([
  "frac", "dfrac", "tfrac", "times", "text", "left", "right", "ln", "sqrt",
  "mu", "theta", "tan", "pm", "div", "pi", "log", "sin", "cos", "leq", "geq",
  "cdot", "circ", "leqslant", "geqslant", "neq", "approx", "alpha", "beta",
  "gamma", "lambda", "sigma", "phi", "Phi", "Sigma", "infty", "int", "sum",
  "Rightarrow",
]);

function repairBackslashWordCorruption(raw) {
  let text = String(raw ?? "");
  if (!text.includes("backslash") && !text.includes("\\{") && !text.includes("\\}")) {
    return text;
  }
  text = text.replace(/\\backslash ?([A-Za-z]+)/g, (whole, word) =>
    BACKSLASH_WORD_COMMANDS.has(word) ? `\\${word}` : whole,
  );
  text = text.replace(/\\backslash ?/g, "");
  text = text
    .replace(/\\left\\\{/g, "LB")
    .replace(/\\right\\\}/g, "RB")
    .replace(/\\\{/g, "{")
    .replace(/\\\}/g, "}")
    .replace(/LB/g, "\\left\\{")
    .replace(/RB/g, "\\right\\}");
  return text;
}

/** Total mark value of a code cell. `B2,1,0` -> 2, `B1 B1` -> 2, `A1 FT` -> 1. */
function markValue(code) {
  if (!code) return 0;
  return [...String(code).matchAll(/\*?(?:DM|DB|M|A|B)(\d+)/gi)].reduce(
    (total, match) => total + Number(match[1] || 1),
    0,
  );
}

/**
 * Does a cell contain human prose, as opposed to bare maths or table debris?
 *
 * This is the test that separates two superficially identical shapes, both of
 * which arrive with no mark code:
 *
 *   legitimate  Marks cell genuinely blank, Guidance carries a real instruction
 *               ("If 0 scored, **SC**: ... **B1**") -- 9709/62 Q7(b)
 *   debris      an embedded numeric sub-table row ("$$-2/3$$ | 9 | 18" / "5")
 *               or a bare separator ("**Or:**") -- 9709/22 Q5(a), 9709/12 Q10
 *
 * Maths is stripped before the test because `\frac` and `\sqrt` would otherwise
 * read as words and make every equation look like prose.
 */
function hasProse(text) {
  if (!text) return false;
  const withoutMaths = String(text)
    .replace(/\$\$?[^$]*\$\$?/g, " ")
    .replace(/\\[A-Za-z]+/g, " ");
  return /[A-Za-z]{3,}/.test(withoutMaths);
}

/** Canonical stored form. Matches the existing distribution: `A1`, `*M1`, `B1 FT`, `DM1`. */
function normalizeCode(body) {
  return body
    .replace(/([0-9])\s*(FT)\b/gi, "$1 $2")
    .replace(/\s*,\s*/g, ",")
    .replace(/\s+/g, " ")
    .trim()
    .toUpperCase();
}

/** Classify a stripped cell. Parenthesised codes signal an alternative method. */
function kindOf(stripped) {
  if (!stripped) return "empty";
  const parenthesised = stripped.match(/^\(([^()]*)\)$/);
  const body = parenthesised ? parenthesised[1].trim() : stripped;
  if (CODE_BODY.test(body)) return parenthesised ? "code_alt" : "code";
  if (SUBTOTAL.test(body)) return "int";
  return "text";
}

function codeBodyOf(stripped) {
  const parenthesised = stripped.match(/^\(([^()]*)\)$/);
  return parenthesised ? parenthesised[1].trim() : stripped;
}

function splitCells(line) {
  return line
    .replace(/^\s*\|/, "")
    .replace(/\|\s*$/, "")
    .split(/(?<!\\)\|/)
    .map((cell) => cell.trim());
}

const isTableLine = (line) => /^\s*\|.*\|\s*$/.test(line.trim());
const isSeparatorRow = (cells) => cells.every((cell) => /^:?-{2,}:?$/.test(cell));

// ---------------------------------------------------------------------------
// Block detection
// ---------------------------------------------------------------------------

/**
 * Split a page into maximal runs of table lines, then keep only the runs that
 * are actually mark-scheme tables.
 *
 * Structural classification, not page-number heuristics. Boilerplate does not
 * reliably end on page 3 -- paper 31's generic material runs to page 8, and the
 * `Annotation | Meaning` table there contains real-looking codes like `DM1`.
 * What it lacks is a question-label row, which is the discriminator.
 */
function findTableBlocks(markdown) {
  const lines = String(markdown ?? "").split(/\r?\n/);
  const blocks = [];
  let current = null;

  for (const line of lines) {
    const trimmed = line.trim();
    if (isTableLine(trimmed)) {
      if (!current) current = [];
      current.push(trimmed);
      continue;
    }
    if (current) {
      blocks.push(current);
      current = null;
    }
    if (PAGE_NOISE.some((pattern) => pattern.test(trimmed))) continue;
  }
  if (current) blocks.push(current);
  return blocks;
}

/** Header layout, or null when the block has no recognisable header. */
function readHeader(cells) {
  const normalized = cells.map((cell) => stripBold(cell).toLowerCase());
  if (normalized[0] !== "question") return null;
  const marksIndex = normalized.findIndex((cell) => cell === "marks");
  if (marksIndex === -1) return null;
  const guidanceIndex = normalized.findIndex((cell) => cell === "guidance");
  return {
    width: cells.length,
    marksIndex,
    guidanceIndex: guidanceIndex === -1 ? marksIndex + 1 : guidanceIndex,
  };
}

/**
 * A headerless block is a mark-scheme continuation only if it both looks like
 * question content and carries at least one mark code. Requiring both keeps the
 * Abbreviations and Annotation tables out.
 */
function looksLikeMarkSchemeBody(rows) {
  const hasQuestionLabel = rows.some((cells) => QUESTION_CELL.test(stripBold(cells[0] ?? "")));
  const hasMarkCode = rows.some((cells) =>
    cells.some((cell) => ["code", "code_alt"].includes(kindOf(stripBold(cell)))),
  );
  return hasQuestionLabel && hasMarkCode;
}

// ---------------------------------------------------------------------------
// Column resolution
// ---------------------------------------------------------------------------

/**
 * Find the Marks column for one row by CONTENT, never by position.
 *
 * Positional parsing is impossible in this corpus. Paper 51 emits 8-column
 * tables because the Answer column contains an embedded frequency table, and
 * within a single block the mark code appears at index 2 on one row and index 6
 * on the next. The header says 6.
 */
function resolveMarksIndex(stripped, layout) {
  const kinds = stripped.map(kindOf);
  const allOtherCellsEmpty = (index) =>
    stripped.every((cell, i) => i === index || cell === "");

  // 1. The header position, when it holds a code.
  if (layout && ["code", "code_alt"].includes(kinds[layout.marksIndex])) {
    return layout.marksIndex;
  }
  // 2. Any code cell, rightmost first. Prefers `**(A1)**` over a bare `2`.
  for (let index = stripped.length - 1; index >= 1; index -= 1) {
    if (["code", "code_alt"].includes(kinds[index])) return index;
  }
  // 2b. A code in the FIRST cell, when the printed Answer cell was blank and
  // OCR dropped the empty leading columns with it.
  //
  // 9709/52 M/J Q6(b) emits `| **A1** | Correct unsimplified expression. |` --
  // two cells in a four-column table, because the row's Question and Answer
  // cells are both empty in the source. The existing shift repair cannot help:
  // it shifts right by one and requires a trailing empty cell, and this row has
  // neither. Without this the row was dropped entirely and the part reconciled
  // at 2 against a printed 3 -- a silently lost mark, on both the primary route
  // and its alternative.
  //
  // Restricted to mark codes on purpose. A bare integer in cell 0 is ambiguous
  // with a question number and stays excluded; `A1` is not, because a question
  // label must match QUESTION_CELL, which requires a leading digit.
  if (["code", "code_alt"].includes(kinds[0])) return 0;
  // 3. An integer in the layout's Marks column, with every cell BEFORE it
  // empty, is a printed subtotal. Guidance after it is allowed: 9709/12 M/J
  // page 17 prints the 6(b) subtotal as `|  |  | **(5)** | Condone the
  // inclusion of pi ... |`, and requiring the whole row to be empty meant that
  // part had no reconciliation anchor at all -- which is precisely why its lost
  // mark went unnoticed.
  //
  // Paper 51's frequency values (`| 1,2,5 | ... | 2 |`) are still excluded,
  // because their Question and Answer cells are not empty.
  const cellsBeforeEmpty = (index) => stripped.every((cell, i) => i >= index || cell === "");
  if (layout && kinds[layout.marksIndex] === "int" && cellsBeforeEmpty(layout.marksIndex)) {
    return layout.marksIndex;
  }
  // 4. No layout to trust, so fall back to the strict rule.
  for (let index = stripped.length - 1; index >= 1; index -= 1) {
    if (kinds[index] === "int" && allOtherCellsEmpty(index)) return index;
  }
  return null;
}

// ---------------------------------------------------------------------------
// Main entry point
// ---------------------------------------------------------------------------

/**
 * Parse every mark-scheme page of one paper.
 *
 * @param {Array<{page_number:number, markdown?:string, raw_markdown?:string}>} pages
 * @returns {{items:Array, printedPartTotals:Object, alternativeGroups:Array, diagnostics:Object}}
 */
function parseMarkSchemePages(pages) {
  const items = [];
  const printedPartTotals = {};
  const alternativeGroups = [];
  const specialCaseGroups = [];
  const diagnostics = {
    realigned_row_count: 0,
    lifted_mark_code_count: 0,
    unparsed_row_count: 0,
    subtotal_row_count: 0,
    table_debris_row_count: 0,
    alternative_block_capped_count: 0,
    shared_answer_row_count: 0,
    table_block_count: 0,
    skipped_block_count: 0,
    merged_mark_value_recovered_count: 0,
  };
  // Per-question diagnostics matter as much as the totals: the fallback
  // decision is made per question, and attributing a paper-wide count to every
  // question would send a whole paper to the paid model because of one bad row.
  const perQuestion = new Map();
  const bump = (questionNumber, field) => {
    if (questionNumber === null || questionNumber === undefined) return;
    if (!perQuestion.has(questionNumber)) {
      perQuestion.set(questionNumber, {
        realigned_row_count: 0,
        lifted_mark_code_count: 0,
        unparsed_row_count: 0,
        subtotal_row_count: 0,
        table_debris_row_count: 0,
        alternative_block_capped_count: 0,
        shared_answer_row_count: 0,
        merged_mark_value_recovered_count: 0,
      });
    }
    perQuestion.get(questionNumber)[field] += 1;
  };

  let layout = null;
  let question = null;
  let partPath = [];
  let altMode = false;
  let scMode = false;
  // True once a "for first N marks" block has awarded its N. While set, rows
  // are primary even if Cambridge keeps parenthesising their codes. Cleared by
  // anything that ends the block: a table header, a new question label, another
  // block header, or a printed subtotal.
  let capSatisfied = false;
  let altGroupIndex = 0;
  let pendingRow = null;

  const partKey = () => partPath.join(".");
  const totalsKey = (q, key) => `${q}|${key}`;

  const sortedPages = [...(pages ?? [])].sort((a, b) => a.page_number - b.page_number);

  for (const page of sortedPages) {
    const markdown = page.markdown ?? page.raw_markdown ?? "";

    for (const block of findTableBlocks(markdown)) {
      const rows = block.map(splitCells).filter((cells) => !isSeparatorRow(cells));
      if (!rows.length) continue;

      const header = readHeader(rows[0]);
      const body = header ? rows.slice(1) : rows;
      if (!body.length) continue;

      if (header) {
        layout = header;
        // A fresh header ends any alternative or special-case block.
        altMode = false;
        scMode = false;
        capSatisfied = false;
        pendingRow = null;
      } else if (!looksLikeMarkSchemeBody(body)) {
        diagnostics.skipped_block_count += 1;
        continue;
      }
      diagnostics.table_block_count += 1;

      for (const rawCells of body) {
        let cells = rawCells;
        let stripped = cells.map((cell) => stripBold(repairBackslashWordCorruption(cell)));
        let marksIndex = resolveMarksIndex(stripped, layout);

        // --- Shift repair -------------------------------------------------
        // Six rows across the batch are shifted one cell left, e.g. paper 42
        // page 21 emits `| $t = 0.5$ ... | **A1** |  |  |`. Retry the row
        // shifted right and accept the alignment that lands a code or subtotal
        // on the header's Marks index.
        const firstCellIsLabel = QUESTION_CELL.test(stripped[0] ?? "");
        const looksShifted =
          layout &&
          marksIndex !== layout.marksIndex &&
          !firstCellIsLabel &&
          stripped[stripped.length - 1] === "";
        if (looksShifted) {
          const shiftedCells = ["", ...cells.slice(0, -1)];
          const shiftedStripped = shiftedCells.map(stripBold);
          const shiftedIndex = resolveMarksIndex(shiftedStripped, layout);
          if (shiftedIndex === layout.marksIndex) {
            cells = shiftedCells;
            stripped = shiftedStripped;
            marksIndex = shiftedIndex;
            diagnostics.realigned_row_count += 1;
            bump(question, "realigned_row_count");
          }
        }

        // --- 1. Question / part label ---------------------------------------
        const labelMatch = stripped[0] ? stripped[0].match(QUESTION_CELL) : null;
        if (labelMatch) {
          question = Number(labelMatch[1]);
          partPath = [...labelMatch[2].matchAll(/\(([A-Za-z0-9]{1,3})\)/g)].map((m) =>
            m[1].toLowerCase(),
          );
          altMode = false;
          scMode = false;
          capSatisfied = false;
          altGroupIndex = 0;
          pendingRow = null;
        }

        if (question === null) continue;

        // Include cell 0 when it holds content rather than a question label.
        // Mistral drops the leading empty cell on continuation rows, e.g.
        // 9709/22 page 9 emits `| Obtain quotient ... | **A1** | |`. Slicing
        // from index 1 unconditionally silently discarded that answer text.
        const answerStart = labelMatch || !stripped[0] ? 1 : 0;
        // When there is no Marks cell the answer must still stop before the
        // Guidance column. Running to the end of the row swallowed the guidance
        // text into the answer, so a guidance-only row came out with identical
        // content and guidance -- which then tripped the duplicate-text rule on
        // every legitimate blank-Answer special-case row.
        const answerEnd = marksIndex === null ? layout?.guidanceIndex ?? undefined : marksIndex;
        const answerCells = stripped.slice(answerStart, answerEnd).filter(Boolean);
        let answerText = answerCells.join(" | ");

        // --- 2. Alternative-method or Special-Case header --------------------
        // Runs AFTER the label step, because paper 42 puts the question label
        // and the block header on the same row.
        const headerCandidate = stripBold(answerCells[0] ?? "");
        // An alternative header can arrive as the ONLY cell on its row, with no
        // leading empty Question cell -- 9709/22 page 9 emits
        // `| **Alternative Method for Question 5(a)** |`. Without this the
        // header was mistaken for content and its block never opened, so every
        // row beneath it counted as a primary mark.

        if (SC_HEADER.test(headerCandidate) && marksIndex === null) {
          scMode = true;
          altMode = false;
          capSatisfied = false;
          specialCaseGroups.push({
            question_number: question,
            part_path: [...partPath],
            heading: headerCandidate,
            mark_value: 0,
            row_sequence_numbers: [],
            _rows: [],
          });
          pendingRow = null;
          continue;
        }

        const altMatch =
          headerCandidate.match(ALT_HEADER) ||
          (BARE_ALT_HEADER.test(headerCandidate) ? [headerCandidate, undefined] : null);
        if (altMatch && marksIndex === null) {
          // `Method 1` is the primary method and closes alternative mode.
          scMode = false;
          capSatisfied = false;
          if (altMatch[1] === "1") {
            altMode = false;
          } else {
            altMode = true;
            altGroupIndex += 1;
            alternativeGroups.push({
              question_number: question,
              part_path: [...partPath],
              group_index: altGroupIndex,
              heading: headerCandidate,
              // null means "runs until the next header or part change", which
              // is the common case. A number means the block covers only that
              // many marks and everything after is shared with the primary.
              mark_cap: alternativeMarkCap(headerCandidate),
              mark_value: 0,
              row_sequence_numbers: [],
              _rows: [],
            });
          }
          pendingRow = null;
          continue;
        }

        const marksCellStripped = marksIndex === null ? "" : stripped[marksIndex];
        const marksKind = marksIndex === null ? "empty" : kindOf(marksCellStripped);

        // --- 3. Printed subtotal --------------------------------------------
        // The single most valuable thing the old pipeline threw away: the
        // examiner's own per-part total, printed in the Marks column. It is
        // reconciliation ground truth that does not depend on the question
        // paper being extracted correctly.
        if (marksKind === "int") {
          // codeBodyOf, not the raw cell: a subtotal inside an alternative
          // block is printed parenthesised, and Number("(5)") is NaN.
          const key = totalsKey(question, partKey());
          const printed = Number(codeBodyOf(marksCellStripped));
          const isParenthesised = marksCellStripped !== codeBodyOf(marksCellStripped);
          // A bare subtotal is the official per-part figure and always wins. A
          // parenthesised one is recorded only when nothing better is known.
          if (!isParenthesised || printedPartTotals[key] === undefined) {
            printedPartTotals[key] = printed;
          }
          diagnostics.subtotal_row_count += 1;
          bump(question, "subtotal_row_count");
          altMode = false;
          scMode = false;
          capSatisfied = false;
          pendingRow = null;
          continue;
        }

