          marksIndex === null
            ? cells[layout?.guidanceIndex ?? cells.length - 1] ?? ""
            : cells.slice(marksIndex + 1).find((cell) => cell.trim()) ?? "";
        let guidanceText = String(guidanceRaw).trim();

