          markCode !== null &&
          !answerText &&
          !guidanceText &&
          pendingRow &&
          pendingRow.part_path.join(".") === partPath.join(".") &&
          pendingRow.content_markdown
        ) {
          answerText = pendingRow.content_markdown;
          sharedAnswer = true;
          diagnostics.shared_answer_row_count += 1;
          bump(question, "shared_answer_row_count");
        }

